from ascii_tool import rasterize_path_ascii, print_ascii

def decode_path(d_str, label=""):
    pts = rasterize_path_ascii(d_str)
    if not pts:
        print(f"{label}: Empty")
        return
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    print(f"\n==================== {label} (Bounds: X=[{min(xs):.1f}, {max(xs):.1f}], Y=[{min(ys):.1f}, {max(ys):.1f}]) ====================")
    print_ascii(pts)

